local class = require(script.Parent.class)
local Prefab = require(script.Parent.Prefab)
local Player = game.Players.LocalPlayer
local module = class("UIBase")

function module:ctor(element)
    self._element = element
end

-- 获取组件
function module:GetComponent(uiObj, component)
    local Component = require(script.Parent.Component)
    return Component.Get(uiObj, component)
end

-- 获取节点
function module:GetNode(objName)
    return Prefab.Get(objName)
end

-- 放置节点
function module:PutNode(obj)
    return Prefab.Put(obj)
end

-- 放置节点
function module:GetUI(path, parent)
    local obj = parent or Player
    for _, name in ipairs(string.split(path, ".")) do
        obj = obj:FindFirstChild(name) or obj:WaitForChild(name, 10)
        if not obj then 
            warn("Not found UI " .. path)
            return nil 
        end
    end
    return obj
end

return module